import{_ as t,a as o}from"./chunks/08-editor-cues-word-mode.Dg1IPIEj.js";import{_ as s,o as r,c as a,a2 as n}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"Timing, cues and auto alignment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/timing.md","filePath":"guide/timing.md"}'),d={name:"guide/timing.md"};function i(c,e,l,h,g,p){return r(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="timing-cues-and-auto-alignment" tabindex="-1">Timing, cues and auto alignment <a class="header-anchor" href="#timing-cues-and-auto-alignment" aria-label="Permalink to &quot;Timing, cues and auto alignment&quot;">​</a></h1><p>Everything in an episode is timed relative to your words. A <strong>cue</strong> is the moment a script line starts in your recording; word times follow from it. Scenes start on lines and elements enter on words:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scenes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">l3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # the scene starts with line 3</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    elements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bucket</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        enter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;l3:&#39;bucket&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the element enters on the word &quot;bucket&quot;</span></span></code></pre></div><p>Re-record a sentence, move its cue, and every animation follows.</p><h2 id="time-expressions" tabindex="-1">Time expressions <a class="header-anchor" href="#time-expressions" aria-label="Permalink to &quot;Time expressions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Meaning</th></tr></thead><tbody><tr><td><code>12.5s</code> (or a YAML number <code>12.5</code>)</td><td>absolute seconds</td></tr><tr><td><code>l7</code></td><td>cue start of line <code>l7</code></td></tr><tr><td><code>l7.end</code></td><td>start of the next line − 0.15 s</td></tr><tr><td><code>l7:&#39;timeout&#39;</code></td><td>first word matching &quot;timeout&quot; (punctuation, tatweel and diacritics ignored)</td></tr><tr><td><code>l7:&#39;request&#39;#2</code></td><td>second match</td></tr><tr><td><code>l7.3</code></td><td>the 4th word (0-based)</td></tr><tr><td><code>@hook</code>, <code>@hook.end</code></td><td>a scene&#39;s start / end</td></tr><tr><td>any of the above <code>+0.4</code> / <code>-0.2</code></td><td>offset in seconds</td></tr></tbody></table><p>Quote YAML strings that contain <code>:</code> or <code>&#39;</code>, for example <code>at: &quot;l3:&#39;bucket&#39;&quot;</code>. Prefer word expressions to absolute seconds: words survive re-recording. The full list is in <a href="./../authoring.html">Writing episodes</a>.</p><h2 id="before-you-record-draft-cues" tabindex="-1">Before you record: draft cues <a class="header-anchor" href="#before-you-record-draft-cues" aria-label="Permalink to &quot;Before you record: draft cues&quot;">​</a></h2><p>A new episode gets <strong>draft cues</strong>, estimated from the length of each line (about 13 characters per second plus a short gap). The preview plays with realistic timing, and validation already checks pacing. Write them with <code>reelforge cue &lt;id&gt; --draft</code>, the <strong>Draft cues</strong> button, or the <code>draft_cues</code> tool.</p><h2 id="recording-tips" tabindex="-1">Recording tips <a class="header-anchor" href="#recording-tips" aria-label="Permalink to &quot;Recording tips&quot;">​</a></h2><ul><li>Record in a quiet room, 20–30 cm from the microphone. Any sample rate works; ReelForge masters the loudness for you (−14 LUFS).</li><li>Read one script line per breath and leave a short pause (0.3–0.5 s) between lines. Pauses make marking faster and give animations room.</li><li>Re-recording later? Upload the new take: ReelForge warns that the voice changed so you can re-check the cues.</li><li>Recorded on a phone or in a noisy room? Turn on <strong>Clean up noise</strong> (episode settings, or <code>audio: { denoise: true }</code>, or <code>reelforge render --denoise</code>). RNNoise removes hiss, hum and room noise from the voice before mastering; in tests it lowers the noise between sentences by about 15 dB without changing the voice level.</li></ul><h2 id="automatic-cues" tabindex="-1">Automatic cues <a class="header-anchor" href="#automatic-cues" aria-label="Permalink to &quot;Automatic cues&quot;">​</a></h2><p>Click <strong>Auto-mark from voice</strong> in Cues mode, <strong>Auto cues</strong> on the dashboard, or run <code>reelforge align &lt;id&gt;</code>. ReelForge already knows the script, so it only has to find where each line and each word starts in the recording. Then listen through once and fix any line by ear (amber lines are the ones it was least sure about). The result is one undo step (<strong>⌘/Ctrl+Z</strong>).</p><p>Two engines:</p><table tabindex="0"><thead><tr><th>Engine</th><th>Needs</th><th>Speed (1 min of voice)</th><th>How it works</th></tr></thead><tbody><tr><td><strong>Pauses</strong> (default)</td><td>nothing</td><td>~0.05 s</td><td>Finds the pauses, then splits the recording into the script&#39;s lines so each line&#39;s length matches its text (dynamic programming). Words follow the syllables.</td></tr><tr><td><strong>Whisper</strong> (optional)</td><td><code>reelforge align --setup</code> once (~180 MB)</td><td>~20 s on a laptop CPU</td><td>A speech model hears the words; only its <strong>timings</strong> are used, matched to your script, so dialects and English terms in Arabic don&#39;t matter. Best for words and music.</td></tr></tbody></table><p>With the optional models installed, a 2 MB voice-activity model (Silero VAD) also tells speech from music, breaths and room noise. Measured on recorded speech with known timings, every line lands within 100 ms (average 15 ms), with or without background music. Words land within 100 ms about 80% of the time, so give precise hits (a stamp on one exact word) a listen in word mode.</p><p><code>reelforge align --status</code> shows what is installed. Models live in your user cache (<code>%LOCALAPPDATA%\\reelforge</code>, <code>~/Library/Caches/reelforge</code> or <code>~/.cache/reelforge</code>; <code>$REELFORGE_CACHE</code> moves it) and are never used while rendering. Cues you marked by hand are never replaced unless you confirm (<code>--force</code> on the command line).</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--engine &lt;e&gt;</code></td><td><code>auto</code> (Whisper when installed, else pauses), <code>dsp</code> or <code>whisper</code></td></tr><tr><td><code>--model &lt;size&gt;</code></td><td>Whisper model: <code>tiny</code>, <code>base</code> (default) or <code>small</code></td></tr><tr><td><code>--no-vad</code></td><td>Detect speech by energy only</td></tr><tr><td><code>--no-words</code></td><td>Line cues only</td></tr><tr><td><code>--force</code></td><td>Replace cues you marked by hand</td></tr><tr><td><code>--dry-run</code></td><td>Print the result without writing <code>cues.json</code></td></tr></tbody></table><h2 id="cues-mode" tabindex="-1">Cues mode <a class="header-anchor" href="#cues-mode" aria-label="Permalink to &quot;Cues mode&quot;">​</a></h2><p>Open the editor and switch to <strong>Cues</strong> (<strong>Alt+2</strong>), or click <strong>Mark cues</strong> on the dashboard. The script is listed on the right, the playhead and waveform are on the timeline.</p><p><img src="`+t+'" alt="Cues mode"></p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><strong>Enter</strong> / <strong>K</strong></td><td>Play / pause</td></tr><tr><td><strong>1 / 2 / 3</strong></td><td>Speed 0.5× / 0.75× / 1× (slower = more accurate)</td></tr><tr><td><strong>Space</strong></td><td>Mark the next unmarked line at the playhead</td></tr><tr><td><strong>Click a line</strong> or <strong>↑ / ↓</strong></td><td>Select a line to re-mark it (then press Space)</td></tr><tr><td><strong>← / →</strong></td><td>Nudge the selected cue by 50 ms (<strong>Shift</strong>: 10 ms)</td></tr><tr><td><strong>Backspace</strong></td><td>Undo the last change</td></tr><tr><td><strong>S</strong> / <strong>A</strong></td><td>Snap the selected cue to the nearest voice onset / toggle auto-snap</td></tr><tr><td><strong>G</strong></td><td>Jump to the selected cue</td></tr><tr><td><strong>W</strong></td><td>Word mode: mark each word of the selected line with Space</td></tr><tr><td><strong>J / L</strong>, <strong>, / .</strong></td><td>Back / forward 1 s, previous / next frame</td></tr></tbody></table><p>Every change is saved instantly to <code>cues.json</code> and can be undone with <strong>⌘/Ctrl+Z</strong>. Lines out of order are shown in red. You can also drag a line&#39;s clip on the <strong>Script</strong> track of the timeline, in Edit or Cues mode.</p><h2 id="word-mode" tabindex="-1">Word mode <a class="header-anchor" href="#word-mode" aria-label="Permalink to &quot;Word mode&quot;">​</a></h2><p>By default ReelForge estimates when each word starts from its length. For precise hits (a stamp landing exactly on “twice”), select the line, press <strong>W</strong>, play, and press <strong>Space</strong> on each word.</p><p><img src="'+o+'" alt="Word mode"></p><h2 id="pacing-checks" tabindex="-1">Pacing checks <a class="header-anchor" href="#pacing-checks" aria-label="Permalink to &quot;Pacing checks&quot;">​</a></h2><p>Validation rule <strong>V-14</strong> warns when a line is spoken faster than about 3.5 words per second (too fast to read in captions) and when the hook starts after 3 s; it also reports silences of 1.5 s or more. Split long lines, or slow down when you record.</p>',28)])])}const f=s(d,[["render",i]]);export{k as __pageData,f as default};
